files.XDG_CONFIG_HOME/satty/overrides.css:
/* Satty chrome -- generated by `burl scheme' (theme.py apply_satty). Do not
 * edit; edits are overwritten on the next wallpaper change.
 *
 * Satty loads this from XDG_CONFIG_HOME/satty/overrides.css on top of its
 * builtin sheet, which is only three rules:
 *
 *   .toolbar        { color: #f9f9f9; background: #00000099; }
 *   .toolbar-bottom { border-radius: 6px 6px 0 0; }
 *   .toolbar-top    { border-radius: 0 0 6px 6px; }
 *
 * i.e. translucent black with light text, ignoring the scheme entirely. The
 * generic GTK-4 widgets inside the toolbars are already themed by the
 * Guix-deployed ~/.config/gtk-4.0/gtk.css; what is left -- and all that is
 * overridden here -- is the toolbar shell itself.
 */

.toolbar {
    color: #34313a;
    /* Alpha, not the flat token: the toolbars float over the screenshot, and
     * an opaque bar hides the very pixels being annotated. Matches the shell's
     * own popout translucency rather than satty's 0x99 black. */
    background: alpha(#f2ecf5, 0.86);
    border: 1px solid alpha(#7d7983, 0.5);
}

/* 12px, matching corner-roundness in config.toml and the shell's own radius --
 * satty's builtin 6px reads square next to everything else on this desktop.
 * Only the edge facing the image is rounded; the outer edge meets the window. */
.toolbar-bottom {
    border-radius: 12px 12px 0 0;
}

.toolbar-top {
    border-radius: 0 0 12px 12px;
}

/* The tool/colour/size buttons. GTK's default flat button is nearly invisible
 * against the translucent bar, so selection state carries the accent. */
.toolbar button {
    color: #34313a;
    border-radius: 8px;
}

.toolbar button:hover {
    background: alpha(#34313a, 0.1);
}

.toolbar button:checked,
.toolbar button:active {
    background: #655789;
    color: #fdf7ff;
}

